// Code node: Cruzar perfis
// Responsabilidade única: cruzar clientes com o catálogo pelo perfil e devolver uma tabela.
// Não cria mensagens nem templates; isso fica no Code node após o Merge.
const webhook = $('Webhook - Clientes1').first().json;
const payload = webhook.body ?? webhook;
const clientes = payload.clientes;
if (!Array.isArray(clientes) || clientes.length === 0) {
  throw new Error('O webhook deve receber uma lista não vazia em clientes[].');
}

const response = $input.first()?.json ?? {};
const csvText = typeof response.data === 'string'
  ? response.data
  : (typeof response.body === 'string' ? response.body : '');
if (!csvText.trim()) throw new Error('Não foi possível obter o conteúdo do CSV de investimentos.');

function parseCsv(text) {
  const rows = [];
  let row = [];
  let cell = '';
  let quoted = false;
  for (let i = 0; i < text.length; i++) {
    const ch = text[i];
    if (ch === '"') {
      if (quoted && text[i + 1] === '"') { cell += '"'; i++; }
      else quoted = !quoted;
    } else if (ch === ',' && !quoted) {
      row.push(cell.trim()); cell = '';
    } else if ((ch === '\n' || ch === '\r') && !quoted) {
      if (ch === '\r' && text[i + 1] === '\n') i++;
      row.push(cell.trim());
      if (row.some(value => value !== '')) rows.push(row);
      row = []; cell = '';
    } else {
      cell += ch;
    }
  }
  row.push(cell.trim());
  if (row.some(value => value !== '')) rows.push(row);
  return rows;
}

function normalize(value) {
  return String(value ?? '').normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '').trim().toLowerCase();
}
function parseNumber(value) {
  const raw = String(value ?? '').replace(/[^0-9,.-]/g, '');
  if (!raw) return 0;
  const normalized = raw.includes(',')
    ? raw.replace(/\./g, '').replace(',', '.')
    : raw;
  const number = Number(normalized);
  return Number.isFinite(number) ? number : 0;
}
function parseSaldo(value) {
  return parseNumber(String(value ?? '').replace(/r\$/i, ''));
}

const rows = parseCsv(csvText.replace(/^\uFEFF/, ''));
if (rows.length < 2) throw new Error('O CSV não possui opções de investimento.');
const headers = rows[0].map(normalize);
const indexes = Object.fromEntries(
  ['perfil', 'produto', 'minimo', 'rentabilidade']
    .map(key => [key, headers.indexOf(key)])
);
if (Object.values(indexes).some(index => index < 0)) {
  throw new Error('CSV deve conter as colunas perfil,produto,minimo,rentabilidade.');
}
const catalogo = rows.slice(1).map(row => ({
  perfil: row[indexes.perfil],
  produto: row[indexes.produto],
  minimo: parseNumber(row[indexes.minimo]),
  rentabilidade: row[indexes.rentabilidade],
})).filter(item => item.perfil && item.produto);

// Uma linha por combinação cliente × produto do perfil. A elegibilidade por saldo
// é um campo da tabela; seleção final e texto ficam no próximo Code node.
const tabelaCruzada = clientes.flatMap((cliente, clienteIndex) => {
  const perfil = normalize(cliente.perfil);
  const opcoesDoPerfil = catalogo.filter(item => normalize(item.perfil) === perfil);
  if (opcoesDoPerfil.length === 0) {
    return [{
      clienteIndex,
      nome: cliente.nome ?? '',
      email: cliente.email ?? '',
      saldo: cliente.saldo ?? '',
      saldoNumerico: parseSaldo(cliente.saldo),
      perfil: cliente.perfil ?? '',
      produto: null,
      minimo: null,
      rentabilidade: null,
      elegivelPorSaldo: false,
    }];
  }
  return opcoesDoPerfil.map(item => ({
    clienteIndex,
    nome: cliente.nome ?? '',
    email: cliente.email ?? '',
    saldo: cliente.saldo ?? '',
    saldoNumerico: parseSaldo(cliente.saldo),
    perfil: cliente.perfil ?? '',
    produto: item.produto,
    minimo: item.minimo,
    rentabilidade: item.rentabilidade,
    elegivelPorSaldo: item.minimo <= parseSaldo(cliente.saldo),
  }));
});

return [{
  json: {
    requestId: payload.requestId ?? null,
    totalClientes: clientes.length,
    totalLinhasTabela: tabelaCruzada.length,
    tabelaCruzada,
  },
}];

// Code node: Montar mensagens (após Merge)
// Responsabilidade: consumir o payload original + tabelaCruzada e montar a resposta.
const merged = $input.first()?.json ?? {};
const payload = merged.body ?? merged;
const clientes = payload.clientes;
const tabela = merged.tabelaCruzada;
if (!Array.isArray(clientes)) {
  throw new Error('O Merge deve preservar o payload original em body.clientes[].');
}
if (!Array.isArray(tabela)) {
  throw new Error('O Merge deve entregar a tabelaCruzada do nó Cruzar perfis.');
}

function normalize(value) {
  return String(value ?? '').normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '').trim().toLowerCase();
}
function moeda(value) {
  return new Intl.NumberFormat('pt-BR', {
    style: 'currency', currency: 'BRL',
  }).format(value);
}
const templates = {
  conservador: 'Seu perfil prioriza previsibilidade e preservação do capital. Compare opções, liquidez e riscos antes de decidir.',
  moderado: 'Seu perfil busca equilíbrio entre previsibilidade e potencial de crescimento. Compare composição, riscos e prazos.',
  arrojado: 'Seu perfil aceita maior oscilação em busca de potencial de crescimento. Diversificação e entendimento dos riscos continuam essenciais.',
};

const resultados = clientes.map((cliente, clienteIndex) => {
  const perfilKey = normalize(cliente.perfil);
  const template = templates[perfilKey];
  if (!template) {
    throw new Error(`Perfil inválido para o cliente ${clienteIndex + 1}: ${cliente.perfil}`);
  }
  const linhasCliente = tabela.filter(row => row.clienteIndex === clienteIndex);
  const elegiveis = linhasCliente
    .filter(row => row.elegivelPorSaldo && row.produto)
    .sort((a, b) => b.minimo - a.minimo);
  const investimento = elegiveis[0] ?? null;
  const saldo = linhasCliente[0]?.saldoNumerico ?? 0;
  const detalhe = investimento
    ? `Uma opção do catálogo para explorar é ${investimento.produto} (aplicação mínima: ${moeda(investimento.minimo)}; rentabilidade indicada no CSV: ${investimento.rentabilidade}).`
    : 'Não há opção do catálogo com aplicação mínima igual ou inferior ao saldo informado; nenhuma opção foi selecionada.';
  const nome = String(cliente.nome ?? 'cliente').trim();
  return {
    cliente: {
      nome,
      email: cliente.email ?? '',
      saldo: cliente.saldo ?? '',
      perfil: cliente.perfil,
    },
    investimento,
    mensagem: `Olá, ${nome}! ${template} ${detalhe} Saldo informado: ${moeda(saldo)}.`,
    aviso: 'Demonstração educacional com dados fictícios. Não constitui recomendação individual de investimento; rentabilidade passada ou estimada não garante retorno.',
  };
});

return [{
  json: {
    requestId: merged.requestId ?? payload.requestId ?? null,
    totalClientes: resultados.length,
    resultados,
  },
}];

// Code node: code normalizar para llm
// Run Once for All Items. Converte resultados[] em N items: um por destinatário.
const itens = $input.all().map(item => item.json ?? {});
if (itens.length === 0) throw new Error('O node não recebeu dados para normalizar.');

const envelope = itens.find(item => Array.isArray(item.resultados)) ?? itens[0];
const resultados = Array.isArray(envelope.resultados) ? envelope.resultados : itens;
if (resultados.length === 0) throw new Error('Não há resultados de clientes para organizar.');

function texto(value, fallback = '') {
  return String(value ?? fallback).trim();
}
function normalizarChave(value) {
  return texto(value).normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, ' ')
    .trim();
}
function normalizarPerfil(value) {
  const perfis = {
    conservador: 'Conservador', conservadora: 'Conservador',
    moderado: 'Moderado', moderada: 'Moderado',
    arrojado: 'Arrojado', arrojada: 'Arrojado',
    agressivo: 'Arrojado', agressiva: 'Arrojado',
  };
  return perfis[normalizarChave(value)] ?? 'Não identificado';
}
function normalizarEmail(value) {
  return texto(value).toLowerCase();
}
function numeroBR(value) {
  if (typeof value === 'number' && Number.isFinite(value)) return value;
  const original = texto(value);
  if (!original) return null;
  const raw = original.replace(/[^0-9,.-]/g, '');
  if (!raw) return null;
  const parsed = Number(raw.includes(',')
    ? raw.replace(/\./g, '').replace(',', '.')
    : raw);
  return Number.isFinite(parsed) ? parsed : null;
}
function moedaBR(value) {
  return value === null ? 'Não informado' : new Intl.NumberFormat('pt-BR', {
    style: 'currency', currency: 'BRL', minimumFractionDigits: 2,
  }).format(value);
}

const registros = resultados.map((resultado, index) => {
  const cliente = resultado.cliente ?? resultado;
  const investimento = resultado.investimento ?? {};
  const emailOriginal = texto(cliente.email ?? resultado.email);
  const perfilOriginal = texto(cliente.perfil ?? resultado.perfil);
  const saldoBrl = numeroBR(cliente.saldo ?? resultado.saldo);
  const minimoBrl = numeroBR(investimento.minimo ?? resultado.aplicacao_minima_brl);
  return {
    requestId: envelope.requestId ?? resultado.requestId ?? null,
    linha: index + 1,
    totalClientes: resultados.length,
    nome: texto(cliente.nome ?? resultado.nome, 'Cliente'),
    email_original: emailOriginal,
    email: normalizarEmail(emailOriginal),
    email_valido: /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(normalizarEmail(emailOriginal)),
    perfil_original: perfilOriginal || 'Não informado',
    perfil_normalizado: normalizarPerfil(perfilOriginal),
    saldo_brl: saldoBrl,
    saldo_formatado: moedaBR(saldoBrl),
    produto_catalogo: texto(investimento.produto ?? resultado.produto_catalogo, 'Sem opção selecionada'),
    aplicacao_minima_brl: minimoBrl,
    aplicacao_minima_formatada: moedaBR(minimoBrl),
    rentabilidade_catalogo: texto(investimento.rentabilidade ?? resultado.rentabilidade_catalogo, 'Não informada'),
    mensagem_base: texto(resultado.mensagem),
    aviso_educacional: texto(resultado.aviso),
  };
});

// O e-mail fica como metadado para a etapa seguinte, mas não é incluído no prompt enviado ao Groq.
return registros.map(registro => {
  const dadosParaMensagem = {
    linha: registro.linha,
    nome: registro.nome,
    perfil: registro.perfil_normalizado,
    saldo: registro.saldo_formatado,
    produto_catalogo: registro.produto_catalogo,
    aplicacao_minima: registro.aplicacao_minima_formatada,
    rentabilidade_catalogo: registro.rentabilidade_catalogo,
    mensagem_base: registro.mensagem_base,
    aviso_educacional: registro.aviso_educacional,
  };
  const promptLLM = [
    'Gere uma mensagem curta e natural em português do Brasil para este único cliente.',
    'Use exclusivamente os dados abaixo; não invente valores, produtos ou rentabilidades.',
    'Não prometa retorno nem faça recomendação individual de investimento.',
    'Preserve o aviso educacional. Retorne somente JSON válido, sem Markdown, no formato {"mensagem":"texto da mensagem"}.',
    '',
    'Dados do cliente (JSON):',
    JSON.stringify(dadosParaMensagem, null, 2),
  ].join('\n');
  return { json: { ...registro, promptLLM } };
});

// Code node: Code - Normalizar saída LLM
// Run Once for All Items. Junta cada resposta do LLM ao item/email correspondente
// do node anterior e devolve um único envelope com resultados por destinatário.
const respostasLLM = $input.all().map(item => item.json ?? {});
const itensPreparados = $('code normalizar para llm').all().map(item => item.json ?? {});
if (respostasLLM.length === 0) throw new Error('O LLM não retornou itens.');
if (respostasLLM.length !== itensPreparados.length) {
  throw new Error(`Quantidade de respostas do LLM (${respostasLLM.length}) diferente da quantidade de destinatários (${itensPreparados.length}). Verifique se o Basic LLM Chain processa cada item de entrada.`);
}

function extrairTexto(item) {
  for (const key of ['text', 'output', 'response', 'answer', 'content']) {
    if (typeof item[key] === 'string' && item[key].trim()) return item[key].trim();
  }
  const generation = item.generations?.[0]?.[0]?.text;
  if (typeof generation === 'string' && generation.trim()) return generation.trim();
  if (typeof item === 'string') return item.trim();
  return JSON.stringify(item);
}
function interpretarResposta(raw) {
  const semMarkdown = raw
    .replace(/^\s*```(?:json)?\s*/i, '')
    .replace(/\s*```\s*$/i, '')
    .trim();
  try {
    const parsed = JSON.parse(semMarkdown);
    if (typeof parsed === 'string') return { mensagem: parsed, parseOk: true };
    const mensagem = parsed.mensagem ?? parsed.message ?? parsed.text;
    if (typeof mensagem === 'string' && mensagem.trim()) {
      return { mensagem: mensagem.trim(), parseOk: true };
    }
    const primeira = parsed.mensagens?.[0]?.mensagem ?? parsed.mensagens?.[0]?.message;
    if (typeof primeira === 'string' && primeira.trim()) {
      return { mensagem: primeira.trim(), parseOk: true };
    }
  } catch (_) {
    // Alguns modelos devolvem texto simples mesmo quando o prompt pede JSON.
  }
  return { mensagem: semMarkdown, parseOk: false };
}

const resultados = respostasLLM.map((resposta, index) => {
  const preparado = itensPreparados[index];
  const bruto = extrairTexto(resposta);
  const interpretado = interpretarResposta(bruto);
  const { promptLLM, ...dadosCliente } = preparado;
  return {
    ...dadosCliente,
    mensagem_llm: interpretado.mensagem,
    resposta_llm_em_json: interpretado.parseOk,
  };
});

return [{
  json: {
    requestId: itensPreparados[0]?.requestId ?? null,
    totalClientes: resultados.length,
    resultados,
  },
}];
